void USchoolLifeWorldSubsystem::InitializeNPCScene()
{
    if (NotificationSession.IsValid()) return;
    Places.Reset();
    for (TActorIterator<ASchoolLifePlaceAnchor> It(GetWorld()); It; ++It)
    {
        checkf(SchoolLifePlaces::IsKnown(It->PlaceId) && !Places.Contains(It->PlaceId), TEXT("PlaceId must be implemented and unique"));
        Places.Add(It->PlaceId, *It);
    }
    NotificationSession = GetWorld()->GetGameInstance()->GetSubsystem<USchoolLifeSessionSubsystem>();
    PresentationHandle = NotificationSession->OnNPCPresentationChanged.AddUObject(this, &USchoolLifeWorldSubsystem::SynchronizeNPCPresentation);
    if (!IsCoast() && !NotificationSession->IsRegionLoading()) RebuildNPCActor();
    else NotificationSession->SetNPCBodyPresent(false);
}

FName USchoolLifeWorldSubsystem::FindNearbyActivityPlace(const ASchoolLifeCharacter* Player) const
{
    if (!IsTickable() || !IsValid(Player) || Player->GetWorld() != GetWorld()) return NAME_None;
    float NearestSquared = FMath::Square(ActivityInteractionDistance);
    FName PlaceId;
    for (const auto& Pair : Places)
    {
        if (!Pair.Value.IsValid()) continue;
        const float DistanceSquared = FVector::DistSquared(Player->GetActorLocation(), Pair.Value->GetActorLocation());
        if (DistanceSquared <= NearestSquared) { NearestSquared = DistanceSquared; PlaceId = Pair.Key; }
    }
    return PlaceId;
}

FSchoolLifeActivityOffer USchoolLifeWorldSubsystem::GetNearbyActivityOffer(ASchoolLifeCharacter* Player) const
{
    const FName PlaceId = FindNearbyActivityPlace(Player);

bool USchoolLifeWorldSubsystem::ResolvePlace(FName PlaceId, FVector& Position) const
{
    const TWeakObjectPtr<ASchoolLifePlaceAnchor>* Anchor = Places.Find(PlaceId);
    if (!Anchor || !Anchor->IsValid()) return false;
    Position = Anchor->Get()->GetActorLocation();
    return true;
}

bool USchoolLifeWorldSubsystem::ResolveNavigablePlace(FName PlaceId, FVector& Position) const
{
    if (!ResolvePlace(PlaceId, Position)) return false;
    UNavigationSystemV1* Navigation = FNavigationSystem::GetCurrent<UNavigationSystemV1>(GetWorld());
    FNavLocation Projected;
    if (!Navigation || !Navigation->ProjectPointToNavigation(Position, Projected, FVector(80, 80, 200))) return false;
    Position = Projected.Location;
    return true;

USchoolLifeSessionSubsystem* Session = GetWorld()->GetGameInstance()->GetSubsystem<USchoolLifeSessionSubsystem>();
const FSchoolLifeNPCRecord Record = Session->GetNPCRecord();
RemoveNPCActor();
FVector Position;
if (!ResolveNavigablePlace(Record.ConfirmedPlaceId, Position))
{
    Session->SetNPCBodyPresent(false);
    UE_LOG(LogTemp, Warning, TEXT("NPC body cannot be restored at confirmed place; session continues abstractly"));
    return;
}
const float HalfHeight = GetDefault<ASchoolLifeNPCCharacter>()->GetCapsuleComponent()->GetScaledCapsuleHalfHeight();
const FTransform Transform(FRotator::ZeroRotator, Position + FVector(0, 0, HalfHeight + 2));

    if (!Controller->IsExecutingJourney(Record.RequestSequence))
    {
        FVector Destination;
        if (!ResolveNavigablePlace(Record.TargetPlaceId, Destination))
        {
            Session->CompleteNPCTravel(Record.PersonId, Record.RequestSequence, false, TEXT("Target unavailable in current NavMesh"));
            return;
        }
        Controller->ExecuteTravel(Record.PersonId, Record.RequestSequence, Destination);
    }
    Controller->SetTravelPaused(IsNPCExecutionPaused(Session));
}

bool USchoolLifeWorldSubsystem::TryNearbyPlayerActivity(ASchoolLifeCharacter* Player)
{
    if (IsInteractionBlocked()) return false;
    if (TryRegionConfirmation(Player)) return true;
    if (!IsTickable() || !IsValid(Player) || Player != UGameplayStatics::GetPlayerPawn(GetWorld(), 0)) return false;
    const auto* Session = GetWorld()->GetGameInstance()->GetSubsystem<USchoolLifeSessionSubsystem>();
    const auto Offer = GetNearbyActivityOffer(Player);
    if (!Offer.bCanStart && Offer.PlaceId != TEXT("LibraryRoom")) { SetHUDNotice(ActivityReasonText(Offer.Reason)); return false; }
    StageActivityConfirmation(Player->GetPersonId(), Offer, Session->GetAbsoluteMinute());
    ConfirmationPlayer = Player;
    HUDNotice.Reset();
    Player->GetCharacterMovement()->StopMovementImmediately();
    Player->ConsumeMovementInputVector();
    SynchronizeNPCPresentation(false); // Pause this existing request, without issuing a new journey.
    return true;

bool USchoolLifeWorldSubsystem::ConfirmPlayerActivity(ASchoolLifeCharacter* Player)
{
    if (bRegionConfirmation) return ConfirmRegion(Player);
    if (!bConfirmationOpen) return false;
    auto* Session = GetWorld()->GetGameInstance()->GetSubsystem<USchoolLifeSessionSubsystem>();
    FVector Anchor;
    const bool CurrentBody = IsTickable() && IsValid(Player) && Player == ConfirmationPlayer.Get()
        && Player == UGameplayStatics::GetPlayerPawn(GetWorld(), 0);
    const bool AtPlace = CurrentBody && ResolvePlace(ConfirmationOffer.PlaceId, Anchor)
        && FVector::DistSquared(Player->GetActorLocation(), Anchor) <= FMath::Square(ActivityInteractionDistance);
    const auto Offer = RecheckConfirmation(Session, CurrentBody ? Player->GetPersonId() : FGuid(), AtPlace);
    const FGuid Id = ConfirmationPlayerId;
    CancelActivityConfirmation();
    if (!Offer.bCanStart) { SetHUDNotice(TEXT("未执行：") + ActivityReasonText(Offer.Reason)); return false; }
    if (Offer.bWaitUntilClass)
    {
        if (!Session->WaitUntilClass(Id, Offer.PlaceId, Offer.EndMinute))
        { SetHUDNotice(TEXT("等待未执行，请重新检查时间与地点。")); return false; }
        const auto Time = Session->GetCalendar().ToDateTime(Offer.EndMinute);
        SetHUDNotice(FString::Printf(TEXT("已等待至%02d:%02d，无收益。请再次按E预览并确认课堂。"), Time.Hour, Time.Minute));
        return true;
    }
    if (!Session->StartPlayerActivity(Id, Offer.ActivityId, Offer.PlaceId))
    { SetHUDNotice(TEXT("活动未执行，请重新检查时间与地点。")); return false; }

