ASchoolLifePlaceAnchor::ASchoolLifePlaceAnchor()
{
    RootComponent = CreateDefaultSubobject<USceneComponent>(TEXT("PlacePosition"));
    static ConstructorHelpers::FObjectFinder<UStaticMesh> Cube(TEXT("/Engine/BasicShapes/Cube"));
    UStaticMeshComponent* Marker = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Marker"));
    Marker->SetupAttachment(RootComponent);
    Marker->SetStaticMesh(Cube.Object);
    Marker->SetRelativeLocation(FVector(0, 0, 2));
    Marker->SetRelativeScale3D(FVector(2.5f, 2.5f, 0.04f));
    Marker->SetCollisionEnabled(ECollisionEnabled::NoCollision);
    Marker->SetCanEverAffectNavigation(false);
    Label = CreateDefaultSubobject<UTextRenderComponent>(TEXT("PlaceLabel"));
    Label->SetupAttachment(RootComponent);
    Label->SetRelativeLocation(FVector(0, 0, 180));

bool USchoolLifeWorldSubsystem::CheckRegionStand(ASchoolLifeCharacter* Player,const FVector& Ground,FVector& Position) const
{
    FCollisionQueryParams Params(SCENE_QUERY_STAT(P09Ground),false,Player);FHitResult Hit;
    if(!GetWorld()->LineTraceSingleByChannel(Hit,Ground+FVector(0,0,200),Ground-FVector(0,0,200),ECC_Visibility,Params)
        || Hit.ImpactNormal.Z<.8)return false;
    // Do not accept a rooftop/obstacle as the intended ground or silently shift a blocked exit.
    if(FMath::Abs(Hit.ImpactPoint.Z-Ground.Z)>40)return false;
    const auto* C=Player->GetCapsuleComponent();Position=Hit.ImpactPoint+FVector(0,0,C->GetScaledCapsuleHalfHeight()+2);
    return !GetWorld()->OverlapBlockingTestByChannel(Position,FQuat::Identity,ECC_Pawn,
        FCollisionShape::MakeCapsule(C->GetScaledCapsuleRadius(),C->GetScaledCapsuleHalfHeight()),Params);

FVector Ground;
if(Home)
{
    if(!ResolveNavigablePlace(TEXT("Home"),Ground)){Reason=TEXT("Navigation pending");return false;}
    Ground+=FVector(0,-150,0);Rotation=FRotator::ZeroRotator;
}
else if(Original)
{
    Ground=Original->GetLocation()-FVector(0,0,Player->GetCapsuleComponent()->GetScaledCapsuleHalfHeight()+2);
    Rotation=Original->Rotator();
    if(CheckRegionStand(Player,Ground,Position)){Reason.Reset();return true;}
    auto* E=FindRegionExit(IsCoast()?FName(TEXT("E09_N")):FName(TEXT("E02_S")));
    if(!E){Reason=TEXT("原区域安全出口缺失。");return false;}
    Ground=E->GetActorLocation()+E->LandingOffset;Rotation=FRotator(0,E->ArrivalYaw,0);

// Resolve the new bodies' required positions before disturbing the live session/navigation.
FVector Home, NPCStart;
if (!ResolveNavigablePlace(TEXT("Home"), Home) || !ResolveNavigablePlace(Candidate.NPC.ConfirmedPlaceId, NPCStart))
{ SaveLoadResult = TEXT("读取失败：家或同学确认地点不可导航。"); SetHUDNotice(SaveLoadResult); return false; }
UNavigationSystemV1* Navigation = FNavigationSystem::GetCurrent<UNavigationSystemV1>(GetWorld());
FNavLocation SafeHome;
if (!Navigation->ProjectPointToNavigation(Home + FVector(0, -150, 0), SafeHome, FVector(80, 80, 200)))
{ SaveLoadResult = TEXT("读取失败：家的安全站位不可用。"); SetHUDNotice(SaveLoadResult); return false; }
FVector Position = SafeHome.Location + FVector(0, 0, Player->GetCapsuleComponent()->GetScaledCapsuleHalfHeight() + 2);
if (!GetWorld()->FindTeleportSpot(Player, Position, Player->GetActorRotation()))
{ SaveLoadResult = TEXT("读取失败：家的安全站位被阻挡。"); SetHUDNotice(SaveLoadResult); return false; }
// Cancel invalidates the old request before its abort callback; the source-controller check
// also rejects any late result after the new NPC body has been created.
// A rejected file/identity/landing must retain the confirmation and its navigation pause.
ClearTransientInteraction();
RemoveNPCActor();
const bool Restored = Session->RestoreSaveSnapshot(Candidate, Reason);
check(Restored); // Already validated above; there is no tick or business callback in between.
Player->GetCharacterMovement()->StopMovementImmediately();
Player->ConsumeMovementInputVector();
Player->BindPerson(Candidate.Player.PersonId);
Player->SetActorLocation(Position, false, nullptr, ETeleportType::TeleportPhysics);
NPCResponseText.Reset();
RebuildNPCActor();
SaveLoadResult = TEXT("Loaded SchoolLife_Main; player at Home, NPC resumes saved intent.");
